import { enrichOrders } from "./app/orders.mjs";
// worst case: productId never found -> full products scan for every order
function bench(n) {
  const products = Array.from({length:n},(_,i)=>({id:i}));
  const orders = Array.from({length:n},(_,i)=>({id:i, productId: -1}));
  const t0 = performance.now();
  const r = enrichOrders(orders, products);
  const t1 = performance.now();
  console.log("no-match n="+n+" comparisons="+(n*n)+" ms="+(t1-t0).toFixed(1)+" product="+String(r[0].product));
